/**
 * @method
 * @name scwin.fnSetCorpBasicInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param items
 * @returns
 * @hidden N
*/
scwin.fnSetCorpBasicInfo = async function (items) {
    /* sdd-asis-lifecycle:begin fnSetCorpBasicInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (items == null) {
        const val = ($c.util.getComponent("dma_fnDownloadReq").get("searchCodeType") || '');
        if (val === "number") {
            await $c.win.alert("조회한 종목코드가 존재하지 않습니다.");
        } else {
            await $c.win.alert("조회한 회사명이 존재하지 않습니다.");
        }
        $c.util.getComponent("dma_fnDownloadReq").set("isurCd", "");
        $c.util.getComponent("dma_fnDownloadReq").set("repIsuCd", "");
        $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", "");
        $c.util.getComponent('AKCKwd').setValue("");
        console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
    } else {
        const isurcd = items.isurcd;
        const repisucd = items.repisucd;
        const repisusrtcd = items.repisusrtcd;
        const comabbr = items.comabbrv;
        $c.util.getComponent("dma_fnDownloadReq").set("isurCd", isurcd);
        $c.util.getComponent("dma_fnDownloadReq").set("repIsuCd", repisucd);
        $c.util.getComponent("dma_fnDownloadReq").set("repIsuSrtCd", repisusrtcd);
        $c.util.getComponent('AKCKwd').setValue(comabbr);
        await scwin.fnInit();
    }
    /* sdd-asis-lifecycle:end */
};
